/* ===== PS01-RIBBON 结构观感（v3.42.0）===== */
/* 菜单行 = 蓝底白字功能区页签行；文件蓝钮语义由首菜单承担 */
QMenuBar {
  background: {chrome_bar};
  border-bottom: 1px solid {border};
  padding: 2px 8px 0;
}
QMenuBar::item {
  color: {chrome_bar_text};
  border-radius: 3px;
  padding: 5px 13px;
}
QMenuBar::item:selected {
  background: rgba(255,255,255,.16);
  color: {chrome_bar_text};
}
QMenuBar::item:pressed {
  background: {bg_soft};
  color: {accent};
}
/* 状态栏 = 蓝底白字 */
QStatusBar {
  background: {chrome_bar};
  border-top: none;
}
QStatusBar QLabel {
  color: {chrome_bar_text};
  border-right: 1px solid {status_sep};
}
QStatusBar QToolButton {
  color: {chrome_bar_text};
}
QStatusBar QToolButton:hover {
  background: rgba(255,255,255,.14);
}
/* 页签：方角 + 选中功能区底色 */
QMainWindow #tabstrip QTabBar::tab:!selected {
  border-radius: 3px 3px 0 0;
}
QMainWindow #tabstrip QTabBar::tab:selected {
  background: {tab_sel_bg};
  color: {tab_sel_text};
  border-top: 2px solid {accent};
}
QMenu::item:selected {
  background: {menu_hover_bg};
  color: {accent};
}

/* RIBBON-1（v3.44.12）：结构化功能区配套——页签行随主题（bg_soft） + 活动页签连编辑区 */
QMainWindow #tabstrip { background: {bg_soft}; }
